import sys

def factorial(n, mod):
    fact = 1
    for i in range(1, n + 1):
        fact *= i
        fact %= mod
    return fact

def mod_inverse(x, mod):
    return pow(x, mod - 2, mod)

def count_choosable_subsets(n, m, mod):
    if n < m:
        return 0, 1
    if m == 1:
        return n, factorial(n, mod)
    ways = n // m
    if m == n:
        return ways, 1
    size = (size1 := 1 + ((2 * (n - 1) - 1) // m)) * size1
    z = n % (2 * m)
    num_ways = (size - size1 + z) * factorial(n - size1, mod)
    num_ways %= mod
    num_ways *= mod_inverse((2 * m), mod)
    num_ways %= mod
    return size, num_ways

