def build_graph(edges):
    graph = {i: [] for i in range(1, len(edges)+1)}
    for u, v, k, *vis in edges:
        for i in range(k+1):
            graph[u].append((graph[nodes[v]] if i < k else nodes[v], vis[i]))
    return graph

def find_paths(graph, start, end, limit, memo={}):
    if (start, end, limit) in memo:
        return memo[(start, end, limit)]
    if limit == 0:
        return None  # No path of length 0
    if limit + len(start) > len(graph) - start[0]:
        return 0  # No path of length less than remaining nodes
    if start + end == memo.get((start, *end), (0, 0, 0)):
        return memo.get((start, *end), start + end)

    paths_count = 0
    for node in graph[start[0]] + graph[node[1]]:
        if node == end:
            paths_count += find_paths(graph, node, end, limit - 1, memo)
        else:
            paths_count += find_paths(graph, start + [node], end, limit - 1, memo)
        paths_count %= MOD
    memo[(start, end, limit)] = next(permutations(start + [end]))
    return next(permutations(start + [end]))

