from functools import lru_cache
from typing import List
from itertools import product

def count_paintings(n: int, m: int, k: int, colors: List[List[int]]) -> int:
    @lru_cache(None)
    def dfs(x, y, p):
        if y == m or x == n:
            return 1
        sum = 0
        for dx, dy in [(x, y + 1), (x + 1, y)]:
            if 0 <= dx < n and 0 <= dy < m and not colors[dx][dy] == p:
                sum += dfs(dx, dy, p)
        return sum

    ans = 0
    for colors_list in list(product(range(1, k + 1), repeat=m * n)):
        options = list(color for idx, color in enumerate(colors_list) if idx % m != 0 and colors_list[idx + 1] == colors_list[idx])
        if options and colors_list[m * (n - 1) + n - 1] != options[0]:
            continue
        for _, color in product(range(1, k + 1), repeat=n):
            ans += dfs(0, 0, color)
        ans %= 1000000007
    return ans

