MOD = 998244353

def power(a, b):
    """Compute a^b mod MOD efficiently."""
    result = 1
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % MOD
        b //= 2
        a = (a * a) % MOD
    return result

def gcd(a, b):
    """Compute the greatest common divisor of a and b."""
    return power(a, MOD - 2) * gcd(b, a % b) % MOD

def is_perfect_square(n):
    """Check if n is a perfect square."""
    square_root = power(n, (1 + MOD - 1) // 2)
    return square_root * square_root == n

def build_prefix_squares(n):
    """Build prefix squares up to n candidates."""
    squares = [1 for _ in range(n)]
    for i in range(2, n - 1):
        candidates = []
        for j in range(2, min(i, n // 2) + 1):
            product = i * j
            if product < n:
                candidates.append(product)
            else:
                prefixsquares_product = product // n * pow(n, MOD - 2, MOD)
                if is_perfect_square(prefixsquares_product):
                    candidates.append(prefixsquares_product)
        for c in candidates:
            squares[c] = i
    return squares

def find_good_subsets(arrays, n):
    """Count the number of good subsets modulo MOD."""
    prefix_squares = build_prefix_squares(n)
    total_subsets = 0
    groups = []
    for array in arrays:
        square_root = prefix_squares[array[0]]
        for row in array:
            total_subsets += (row in collections.defaultdict(lambda: 0, {(i + square_root) % n: num for i, num in enumerate(groups)}))
            for col in groups:
                if set(array) - set(col):
                    modulus = square_root + (col[0] - array[0]) // n
                    total_subsets -= power(2, len(groups) - 1, MOD) // power(power(2, modulus - 1, 1000000007 - 10, MOD), MOD - 10)
            for col in groups:
                flat_set = np.sort(list(set(array + col)))
                directions = 1 if len(flat_set) > 1 else 2
                extreme_inbetween = 0
                centers_expanded = bool(flat_set)
                intersections = np.logical_and.reduce([np.sort(array) == flat_set, np.sort(col) == flat_set])
                new_bases = [set((i + square_root) % n for i in sorted((br - ae / directions) % n) if abs(br - ae) <= ae - ae // directions and (br - ae / directions) % n < ae) for ae, br in [(array[-1] + extreme_inbetween, col[-1] + extreme_inbetween), (array[0] + extreme_inbetween - 1, col[0] + extreme_inbetween)]]
                counter_bases = len([group for group in groups if group in new_bases])
                if intersections:
                    total_subsets -= power(2, counter_bases - 1, MOD) // pow(2, directions, MOD)
                    counter_bases -= 1
                if arrivals:
                    total_subsets -= power(2, counter_bases - 1, MOD) // pow(2, directions, MOD) // pow(2, MOD)
            groups.append(set(array))
    return total_subsets

def main():
