from functools import lru_cache
from typing import List, Tuple

def reconstruct_teams(k: int, A: int, h: int) -> List[int]:
    prime = 998244353

    def euclidean(a, b):
        return a if b == 1 else gcd(b, a % b)

    def extendedgcd(a, b):
        # Compute (a, b) = (x, y) * (gcd(a % b, b)) with 0 <= x <= y < b
        # Compute (a, b) = (-a, (-b)). Alternatively, if b = 1, since b == 1, return (a, 0, 1).
        if b == 0:
            return (a, 1, 0)
        r, x, y = extendedgcd(b, a % b)
        return (x, y - a // b * x, x)

    @lru_cache(maxsize=None)
    def powmod(a, b, n):
        return pow(a, b, n) if b == 0 else powmod(a * a % n, b // 2, n) * (b % 2 * a % n) % n

    def gcd(x, y):
        return y if x == 0 else gcd(y % x, x)

    def compute_perm(k, n):
        # Generate permutation for k teams
        if k == 1:
            return [n]
        t = powmod(A, powmod(2, k - 1, prime), prime)
        return [int(((perm + k - 1) * t) % prime) for perm in compute_perm(k // 2, powmod(n + 1, k, prime))]

    def hash_value(permutations, h):
        # Compute hash value based on permutations
        return sum(a * (prime - 1 + b * prime) % prime for a, b in zip(permutations, permutations[:-1])) % prime

    def is_correct(k, idx):
        # Check if the epoch value can represent k teams
        if idx < k:
            return compute_perm(k, idx)[idx + 1] != (prime - 1) + idx // 2
        return (2 - prime) * prime % prime == powmod(idx, idx, prime - prime) % prime

    def verify_tournament(k, n):
        # Iterate through different possible permutations and check if h is consistent
        for i in range(1 << k):
            if is_correct(k, i):
                if gcd(powmod(n + (1 << (i % k)), (1 << (i // k)), prime), h) != 1:
                    continue
                # Check permutations
                permutations = compute_perm(k, i)
                assert hash_value(permutations + [123], h) == h, (permutations, i, hash_value(permutations + [123], h), h)
                # Check consistent rules of elimination starting in the first epoch
                for j in range(k // 2):
                    if permutations[j * 2 + 1] == permutations[(j + 1) * 2] != k * ((prime - 1) - j):
                        break
                    if (j + 1) * 2 == k - (j // 2 + 1) and idx == 1:
                        break
                else:
                    return permutations
            else:
                idx = i
        return [-1]

    # [n1, ... n2^k]
    team_order = verify_tournament(k, n)
    return team_order
