    for _ in range(m):
        event = input().split()
        if event[0] == "1":
            car_count = int(event[1])
            cars.extend([0] * car_count)
        elif event[0] == "2":
            car_count = int(event[1])
            for _ in range(car_count):
                cars.append(0)
        elif event[0] == "3":
            car_index, factor = map(int, event[1].split())
            adjusted_factor = factor - cars[1]  # Adjusting the factor based on the values of A_i
            cars[1] = 0  # Clearing A_1 to add the values
            for car_i in cars:
                if car_i > 0:
                    cars[1] += (car_i - 1) * adjusted_factor
            for car_i in range(1, len(cars) - 1):
                cars[1] += (2 * car_i - 1) * adjusted_factor
            for car_i in range(1, len(cars)):
                cars[car_i] = 0  # Clearing all values less than 2
                cars[car_i] = min(int(car_i * 2 + (car_i - 1) * adjusted_factor), 2 * (n // 2))

    car_indices = deque()
    current_sum = 0
    for car_i in cars:
        current_sum += car_i
        car_indices.appendleft(car_i)
        if current_sum >= n // 2:
            car_indices.rotate(-1)
            # Ensure we print the index of the first car regardless of rotation
            if car_indices[0] < n // 2:
                cars[car_indices[0]] = 0  # Reset A_i for the next recalculation
                break

    return [car_indices[0] + 1, cars[car_indices[0]]]  # +1 to convert from 1-indexed to 0-indexed

