from math import gcd

def least_common_multiple(x, y):
    return (x * y) // gcd(x, y)

def find_solution(N, M):
    factorization = {}
    divisor = N

    # Factorize N by M and calculate the size of the subset
    while divisor >= M:
        if M in factorization:
            del factorization[M]
        else:
            factorization[M] = 0
        divisor //= M

    pm = 1
    for M in sorted(factorization.keys(), reverse=True):
        if pm > N // M and len(factorization) > 1:
            # Invalid choice, skip
            return None, None
        else:
            lm = least_common_multiple(pm, M)
            for m in range(pm, N // M + 1, lm):
                # print(f"lcm {m} * {M}")
                if pm * M % (m * M) == 0:
                    idx = len(factorization) + 1
                    if idx != N // M:
                        factorization[M] -= 1
                        break
                while factorization[M] > 0:
                    factorization[M] -= 1
                    pm *= M

            if idx == N // M:
                # Calculate the number of ways
                ways = 1
                for item in factorization.items():
                    factorized, count = item
                    ways = (ways * count) % 998244353
                return idx, ways

