import sys

def read_input():
    n = int(sys.stdin.readline().strip())
    m = int(sys.stdin.readline().strip())
    edges = [tuple(map(int, sys.stdin.readline().strip().split())) for _ in range(n - 1)]
    queries = [tuple(map(int, sys.stdin.readline().strip().split())) for _ in range(m)]
    return n, m, edges, queries

def build_tree(edges):
    tree = [[] for _ in range(len(edges) + 1)]
    for e in edges:
        tree[e[0]].append(e[1])
        tree[e[1]].append(e[0])
    return tree

def find_path(tree, start, end, seen):
    path = []
    while start != end:
        path.append(start)
        for neighbor in tree[start]:
            if neighbor not in seen and neighbor != end:
                tree[start].remove(neighbor)
                start = neighbor
                seen.add(start)
                break
    path.append(end)
    return path[::-1]

def main():
    n, m, edges, queries = read_input()
    tree = build_tree(edges)
    queries_labels = [q[0] for q in queries]
    queries_args = [q[1] for q in queries]
    res = []
    for label in queries_labels:
        if label == 1:
            start = queries_args[queries_labels.index(label)]
            closest_red = edges[start - 1][0]
            res.append((closest_red, abs(closest_red - start)))
        if label == 2:
            vi = queries_args[queries_labels.index(label)]
            if closest_red == vi:
                res.append((closest_red, 0))
            else:
                red_neighbors = [node for node in tree[vi] if node != start - 1]
                if not red_neighbors:
                    res.append((-1, -1))  # No red neighbor, nearest blue neighbor
                else:
                    min_distance, closest_red = min((abs(node - vi), node) for node in red_neighbors)
                    res.append((closest_red, min_distance))
    for r in res:
        print(" ".join(map(str, r)))

if __name__ == "__main__":
