from collections import deque

class Train:
    def __init__(self):
        self._cars = deque()

    def add_to_head(self, num):
        self._cars.appendleft(num)

    def add_to_tail(self, num):
        self._cars.append(num)

    def recalculate(self, b, s):
        self._cars.appendleft(b + (s - 1) * self.length())
        self._cars.append(b + (s - 1) * self.length())

    def output(self, query):
        if query[0] == 3:
            b, s = query[1], query[2]
            self.recalculate(b, s)

        if query[0] == 1:
            num = query[1]
            self._cars.appendleft(num)
        elif query[0] == 2:
            num = query[1]
            self._cars.append(num)

        if len(self._cars) > 1:
            j, result = self._cars[0]
            for i in range(len(self._cars) - 1):
                j = min(j, self._cars[i + 1])
                result = min(result, j)
            return j, result
        else:
            return self._cars[0], self._cars[0]

def process_queries(n, m, records):
    train = Train()
    for query in records:
        op, *args = query
        result = train.output(op, args)
        print(result)

