def paint_board(n, m, k, board):
    adj = defaultdict(list)
    for x in range(n-1, -1, -1):
        for y in range(m-1, -1, -1):
            if board[x][y] != 0:
                adj[board[x][y]-1].append((x+1 if x+1 < n else 0, y+1 if y+1 < m else 0))
    @lru_cache(None)
    def dfs(color, x, y):
        if x == n-1 and y == m-1:
            return 1
        res = 0
        for nx, ny in adj[color]:
            if nx >= 0 and ny >= 0 and board[nx][ny] == 0:
                res += dfs(color, nx, ny)
        return res % 1000000007
    return dfs(0, 0, 0) % 1000000007

